using DriveOS.Application.Abstractions.Messaging;using DriveOS.Application.Abstractions.Time;using DriveOS.Modules.CurriculumPedagogy.Application.Persistence;using DriveOS.Modules.CurriculumPedagogy.Domain.LicenseCategories;using DriveOS.SharedKernel.Identifiers;using DriveOS.SharedKernel.Results;
namespace DriveOS.Modules.CurriculumPedagogy.Application.LicenseCategories;
public sealed record CreateLicenseCategoryCommand(OrganizationId OrganizationId,string CountryCode,string Code,string Name,string? Description,UserId ActorUserId):ICommand<LicenseCategoryDefinitionId>;
public sealed record ActivateLicenseCategoryCommand(OrganizationId OrganizationId,LicenseCategoryDefinitionId Id,UserId ActorUserId):ICommand;
internal sealed class CreateLicenseCategoryCommandHandler(ILicenseCategoryDefinitionRepository repo,ICurriculumPedagogyUnitOfWork uow,IClock clock):ICommandHandler<CreateLicenseCategoryCommand,LicenseCategoryDefinitionId>{public async Task<Result<LicenseCategoryDefinitionId>> Handle(CreateLicenseCategoryCommand c,CancellationToken ct){if(await repo.ExistsAsync(c.OrganizationId,c.CountryCode,c.Code,ct))return Result.Failure<LicenseCategoryDefinitionId>(LicenseCategoryDefinitionErrors.ScopeAlreadyExists);var r=LicenseCategoryDefinition.Create(LicenseCategoryDefinitionId.New(),c.OrganizationId,c.CountryCode,c.Code,c.Name,c.Description);if(r.IsFailure)return Result.Failure<LicenseCategoryDefinitionId>(r.Error);r.Value.SetCreatedAudit(clock.UtcNow,c.ActorUserId);await repo.AddAsync(r.Value,ct);await uow.CommitAsync(ct);return Result.Success(r.Value.Id);}}
internal sealed class ActivateLicenseCategoryCommandHandler(ILicenseCategoryDefinitionRepository repo,ICurriculumPedagogyUnitOfWork uow,IClock clock):ICommandHandler<ActivateLicenseCategoryCommand>{public async Task<Result> Handle(ActivateLicenseCategoryCommand c,CancellationToken ct){var x=await repo.GetByIdForUpdateAsync(c.Id,ct);if(x is null||x.OrganizationId!=c.OrganizationId)return Result.Failure(LicenseCategoryDefinitionErrors.NotFound);var r=x.Activate(c.ActorUserId,clock.UtcNow);if(r.IsFailure)return r;await uow.CommitAsync(ct);return Result.Success();}}
